const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();

const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;

let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content || 
           (originalMsg.data ? originalMsg.data : '') || '';

    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) {
            chatId = originalMsg.message.chat.id;
        } else if (originalMsg.chat) {
            chatId = originalMsg.chat.id;
        }
    }

    if (originalMsg.from) {
        userId = originalMsg.from.id;
    }

    const callbackQueryId = payload.callback_query_id || payload.id || 
                            (originalMsg.id ? originalMsg.id.toString() : null) ||
                            (originalMsg.query_id ? originalMsg.query_id.toString() : null);

    if (callbackQueryId) {
        answerCallback = {
            payload: {
                callback_query_id: callbackQueryId,
                text: '',
                show_alert: false
            },
            topic: 'answerCallbackQuery'
        };
    }
}

if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, answerCallback].filter(m => m !== null);
}

if (!flow.get('garden_telegram_chat_ids')) {
    flow.set('garden_telegram_chat_ids', []);
}
const chatIds = flow.get('garden_telegram_chat_ids');
if (!chatIds.includes(chatId)) {
    chatIds.push(chatId);
    flow.set('garden_telegram_chat_ids', chatIds);
}

const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);

if (!command.startsWith('/garden')) {
    return [null, answerCallback].filter(m => m !== null);
}

msg.telegram = {
    chatId: chatId,
    userId: userId,
    messageId: messageId,
    command: command,
    args: args,
    originalText: text
};

if (command === '/garden_on') {
    msg.topic = 'garden_on';
} else if (command === '/garden_off') {
    msg.topic = 'garden_off';
} else if (command === '/garden_toggle') {
    msg.topic = 'garden_toggle';
} else if (command === '/garden_status') {
    msg.topic = 'garden_status';
} else if (command === '/garden_help') {
    msg.topic = 'garden_help';
} else {
    msg.topic = 'garden_unknown';
}

return [msg, answerCallback].filter(m => m !== null);

if (msg.payload && msg.payload.callback_query_id) {
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

const timestamp = new Date().toISOString();
const requestId = `telegram-garden-on-${Date.now()}`;
const telegramData = msg.telegram;

msg.payload = 'ON';
msg.topic = 'cmnd/sonoffPower320D_afara/Power';
msg.telegram = telegramData;
msg.telegram.requestId = requestId;

const confirmationMsg = {
    ...msg,
    payload: {
        chatId: telegramData.chatId,
        type: 'message',
        content: `⚡ Turning ON Garden Power...\n\nRequest ID: ${requestId}`,
        parse_mode: 'Markdown'
    },
    topic: 'send'
};

return [msg, confirmationMsg];

const timestamp = new Date().toISOString();
const requestId = `telegram-garden-off-${Date.now()}`;
const telegramData = msg.telegram;

msg.payload = 'OFF';
msg.topic = 'cmnd/sonoffPower320D_afara/Power';
msg.telegram = telegramData;
msg.telegram.requestId = requestId;

const confirmationMsg = {
    ...msg,
    payload: {
        chatId: telegramData.chatId,
        type: 'message',
        content: `⚫ Turning OFF Garden Power...\n\nRequest ID: ${requestId}`,
        parse_mode: 'Markdown'
    },
    topic: 'send'
};

return [msg, confirmationMsg];

const timestamp = new Date().toISOString();
const requestId = `telegram-garden-toggle-${Date.now()}`;
const telegramData = msg.telegram;

msg.payload = 'TOGGLE';
msg.topic = 'cmnd/sonoffPower320D_afara/Power';
msg.telegram = telegramData;
msg.telegram.requestId = requestId;

const confirmationMsg = {
    ...msg,
    payload: {
        chatId: telegramData.chatId,
        type: 'message',
        content: `🔄 Toggling Garden Power...\n\nRequest ID: ${requestId}`,
        parse_mode: 'Markdown'
    },
    topic: 'send'
};

return [msg, confirmationMsg];

// Read from GLOBAL context (shared across all flows)
const gardenState = global.get('garden_power_state') || {};

let statusText = `⚡ *Garden Power Status*\n\n`;

const powerStatus = gardenState.powerStatus || 'UNKNOWN';
const statusEmoji = powerStatus === 'ON' ? '🟢' : (powerStatus === 'OFF' ? '⚫' : '🟡');
statusText += `${statusEmoji} *Power*: ${powerStatus}\n\n`;

statusText += '*Energy Metrics:*\n';
statusText += `⚡ Voltage: ${gardenState.voltage || 'N/A'} V\n`;
statusText += `⚡ Current: ${gardenState.current || 'N/A'} A\n`;
statusText += `⚡ Power: ${gardenState.power || 'N/A'} W\n\n`;

statusText += '*Consumption:*\n';
statusText += `📊 Total: ${gardenState.total || 'N/A'} kWh\n`;
statusText += `📅 Today: ${gardenState.today || 'N/A'} kWh\n`;
statusText += `📅 Yesterday: ${gardenState.yesterday || 'N/A'} kWh\n`;

if (gardenState.lastUpdate) {
    const lastUpdate = new Date(gardenState.lastUpdate).toLocaleString('ro-RO');
    statusText += `\n🕐 Last update: ${lastUpdate}`;
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: statusText,
    parse_mode: 'Markdown'
};
msg.topic = 'send';

return msg;

const helpText = `⚡ *Garden Power Control Bot*\n\n` +
    `*Available Commands:*\n\n` +
    `🟢 \`/garden_on\`\n` +
    `   Turn ON garden power\n\n` +
    `⚫ \`/garden_off\`\n` +
    `   Turn OFF garden power\n\n` +
    `🔄 \`/garden_toggle\`\n` +
    `   Toggle garden power state\n\n` +
    `📊 \`/garden_status\`\n` +
    `   Get power status & metrics\n\n` +
    `❓ \`/garden_help\`\n` +
    `   Show this help message\n\n` +
    `*Monitoring:*\n` +
    `• Voltage, Current, Power\n` +
    `• Total/Today/Yesterday consumption\n` +
    `• Real-time status updates\n\n` +
    `*Quick Actions:*\n` +
    `Use the buttons below:`;

const inlineKeyboard = {
    inline_keyboard: [
        [
            { text: '🟢 Turn ON', callback_data: '/garden_on' },
            { text: '⚫ Turn OFF', callback_data: '/garden_off' }
        ],
        [
            { text: '🔄 Toggle', callback_data: '/garden_toggle' },
            { text: '📊 Status', callback_data: '/garden_status' }
        ],
        [
            { text: '❓ Help', callback_data: '/garden_help' }
        ]
    ]
};

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: helpText,
    parse_mode: 'Markdown',
    options: {
        reply_markup: JSON.stringify(inlineKeyboard)
    }
};
msg.topic = 'send';

return msg;

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: `❓ Unknown garden power command: ${msg.telegram.originalText}\n\nType /garden_help for available commands.`
};
msg.topic = 'send';

return msg;
